  // ===== Режим тревоги (вместо стандартного alert() на ошибках) =====
  let alarmTimer = null;
  let sharedAudioCtx = null;
  function playAlarmSound(){
    try{
      sharedAudioCtx = sharedAudioCtx || new (window.AudioContext || window.webkitAudioContext)();
      const ctx = sharedAudioCtx;
      if(ctx.state === 'suspended') ctx.resume();
      const now = ctx.currentTime;
      [0, 0.18].forEach(offset=>{
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'square';
        osc.frequency.setValueAtTime(880, now + offset);
        osc.frequency.exponentialRampToValueAtTime(440, now + offset + 0.15);
        gain.gain.setValueAtTime(0.001, now + offset);
        gain.gain.exponentialRampToValueAtTime(0.08, now + offset + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.001, now + offset + 0.16);
        osc.connect(gain).connect(ctx.destination);
        osc.start(now + offset);
        osc.stop(now + offset + 0.17);
      });
    } catch(e){
      // Web Audio недоступен — тревога остаётся визуальной
    }
  }
