  // ===== Универсальное хранилище: window.storage внутри Claude, localStorage — при локальном открытии файла =====
  const hasClaudeStorage = typeof window.storage !== 'undefined' && window.storage !== null;
  async function storageGet(key){
    if(hasClaudeStorage){
      try{ return await window.storage.get(key); } catch(e){ return null; }
    }
    try{
      const v = localStorage.getItem(key);
      return v !== null ? {key, value: v, shared: false} : null;
    } catch(e){ return null; }
  }
  async function storageSet(key, value){
    if(hasClaudeStorage){
      try{ return await window.storage.set(key, value); } catch(e){ return null; }
    }
    try{ localStorage.setItem(key, value); return {key, value, shared:false}; } catch(e){ return null; }
  }
  async function storageDelete(key){
    if(hasClaudeStorage){
      try{ return await window.storage.delete(key); } catch(e){ return null; }
    }
    try{ localStorage.removeItem(key); return {key, deleted:true, shared:false}; } catch(e){ return null; }
  }

  // ===== Память (window.storage) =====
  // ===== Бортовой журнал инцидентов =====
  let incidentLog = [];
  function logIncident(text){
    incidentLog.push({ time: new Date(), text });
    if(incidentLog.length > 200) incidentLog.shift();
  }
  function showIncidentLog(){
    if(incidentLog.length === 0) return "Бортовой журнал пуст. Инциденты ещё не зафиксированы, Doctor Wels.";
    const entries = incidentLog.slice(-12).map(e=>{
      const t = e.time.toLocaleTimeString('ru-RU');
      return `[${t}] ${e.text}`;
    });
    return "БОРТОВОЙ ЖУРНАЛ S.T.A.R. LABS — последние записи:\n" + entries.join('\n');
  }
  function exportIncidentLog(){
    if(incidentLog.length === 0){
      notify('Журнал пуст — экспортировать нечего');
      return;
    }
    let text = `GIDEON — бортовой журнал S.T.A.R. LABS (Doctor Wels)\n${new Date().toLocaleString('ru-RU')}\n${'='.repeat(40)}\n\n`;
    incidentLog.forEach(e=>{
      text += `[${e.time.toLocaleString('ru-RU')}] ${e.text}\n`;
    });
    const blob = new Blob([text], {type:'text/plain;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `gideon-incident-log-${Date.now()}.txt`;
    a.click();
    URL.revokeObjectURL(url);
    notify('Бортовой журнал экспортирован в файл');
  }

  // ===== "Аномалии временной линии" — реальные данные погоды, поданные в стиле Гидеона =====
  async function checkTimelineAnomalies(){
    if(!navigator.geolocation){
      return "Модуль геолокации недоступен в этом браузере. Сканирование аномалий невозможно.";
    }
    try{
      const pos = await new Promise((resolve, reject)=>{
        navigator.geolocation.getCurrentPosition(resolve, reject, {timeout: 6000});
      });
      const { latitude, longitude } = pos.coords;
      const url = `https://api.open-meteo.com/v1/forecast?latitude=${latitude}&longitude=${longitude}&current=temperature_2m,wind_speed_10m,weather_code&timezone=auto`;
      const res = await fetch(url);
      if(!res.ok) throw new Error('bad response');
      const data = await res.json();
      const c = data.current;
      const temp = c.temperature_2m;
      const wind = c.wind_speed_10m;
      const code = c.weather_code;

      let severity = 'НИЗКАЯ';
      if(wind > 50 || temp > 38 || temp < -25) severity = 'КРИТИЧЕСКАЯ';
      else if(wind > 25 || temp > 30 || temp < -10) severity = 'ПОВЫШЕННАЯ';

      const codeDescriptions = {0:'ясное искажение поля',1:'частичная нестабильность',2:'умеренная турбулентность',3:'плотная завеса',45:'аномальный туман',61:'осадки в тайм-линии',71:'кристаллизация потока',95:'грозовой разряд Спидфорса'};
      const phenomenon = codeDescriptions[code] || 'неклассифицированное отклонение';

      logIncident(`Сканирование аномалий: ${severity}, ${temp}°C, ветер ${wind} км/ч`);
      if(severity === 'КРИТИЧЕСКАЯ') triggerAlarm();
      return `СКАНИРОВАНИЕ ЗАВЕРШЕНО.\nУровень отклонения временной линии: ${severity}\nТемпературный градиент: ${temp}°C\nСкорость потока (ветер): ${wind} км/ч\nХарактер аномалии: ${phenomenon}\n\n(Данные реальные, с метеоспутников — Гидеон просто подаёт их в стиле Спидфорса.)`;
    } catch(err){
      return "Не удалось получить доступ к геолокации или спутниковым данным. Проверьте разрешения браузера, Doctor Wels.";
    }
  }

  let conversation = []; // [{role:'user'|'assistant', content:'...'}]
