  async function updateStreak(){
    const streakEl = document.getElementById('streak-readout');
    if(!streakEl) return;
    try{
      const stored = await storageGet('gideon-streak');
      let data = { lastDate: null, count: 0 };
      if(stored && stored.value){
        try{ data = JSON.parse(stored.value); } catch(e){}
      }
      const today = todayStr();
      if(data.lastDate !== today){
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        const yStr = `${yesterday.getFullYear()}-${yesterday.getMonth()+1}-${yesterday.getDate()}`;
        data.count = (data.lastDate === yStr) ? (data.count + 1) : 1;
        data.lastDate = today;
        await storageSet('gideon-streak', JSON.stringify(data));
      }
      streakEl.textContent = data.count > 1
        ? `🔥 СВЯЗЬ СО СПИДФОРСОМ: ${data.count}-Й ДЕНЬ ПОДРЯД`
        : '🔥 СВЯЗЬ СО СПИДФОРСОМ УСТАНОВЛЕНА';
    } catch(e){
      // Тихо игнорируем — счётчик не критичен для работы сайта
    }
  }

  async function loadMemory(){
    try{
      const result = await storageGet(MEM_KEY);
      if(result && result.value){
        conversation = JSON.parse(result.value);
        log.innerHTML = "";
        if(conversation.length === 0){
          addLine("Инициализация завершена. Ожидаю ваш запрос, Doctor Wels.", 'gideon');
        } else {
          conversation.forEach(m => addLine(m.content, m.role === 'user' ? 'user' : 'gideon'));
          addLine("Память предыдущего сеанса восстановлена, Doctor Wels.", 'gideon');
        }
      }
    } catch(e){
      // ключа ещё нет — первый запуск, ничего страшного
    }
  }

  async function saveMemory(){
    try{
      await storageSet(MEM_KEY, JSON.stringify(conversation.slice(-40)));
    } catch(e){
      console.error('Не удалось сохранить память:', e);
    }
  }

  async function clearMemory(){
    conversation = [];
    try{ await storageDelete(MEM_KEY); } catch(e){}
    log.innerHTML = "";
    addLine("Память временной линии очищена. Начинаю с чистого листа, Doctor Wels.", 'gideon');
    notify('Память очищена');
  }

  // ===== Голос =====
  let voiceOn = true;
  function toggleVoice(){
    voiceOn = !voiceOn;
    const btn = document.getElementById('voice-toggle');
    btn.textContent = voiceOn ? '🔊 ГОЛОС' : '🔇 ГОЛОС';
    btn.classList.toggle('off', !voiceOn);
    if(!voiceOn) window.speechSynthesis.cancel();
    notify(voiceOn ? 'Голос включён' : 'Голос выключен');
  }
  function speak(text){
    if(!voiceOn || !('speechSynthesis' in window)) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'ru-RU';
    u.rate = 1.02;
    u.pitch = 0.85;
    window.speechSynthesis.speak(u);
  }

  // ===== Голосовой ввод =====
  const SpeechRecognitionAPI = window.SpeechRecognition || window.webkitSpeechRecognition;
  let recognizer = null;
  let listening = false;
  if(SpeechRecognitionAPI){
    recognizer = new SpeechRecognitionAPI();
    recognizer.lang = 'ru-RU';
    recognizer.continuous = false;
    recognizer.interimResults = true;

    recognizer.onresult = (e)=>{
      let text = '';
      for(let i=0;i<e.results.length;i++) text += e.results[i][0].transcript;
      cmdInput.value = text;
    };
    recognizer.onend = ()=>{
      listening = false;
      document.getElementById('mic-btn').classList.remove('listening');
      document.getElementById('mic-btn').textContent = '🎤 ВВОД';
      if(cmdInput.value.trim()) sendCmd();
    };
    recognizer.onerror = (e)=>{
      listening = false;
      document.getElementById('mic-btn').classList.remove('listening');
      document.getElementById('mic-btn').textContent = '🎤 ВВОД';
      notify(e.error === 'not-allowed' ? '⚠ Доступ к микрофону запрещён' : '⚠ Голосовой ввод недоступен');
    };
  }
  function togglelistening(){
    if(!recognizer){
      notify('⚠ Браузер не поддерживает голосовой ввод (нужен Chrome/Edge)');
      return;
    }
    if(listening){
      recognizer.stop();
      return;
    }
    try{
      recognizer.start();
      listening = true;
      document.getElementById('mic-btn').classList.add('listening');
      document.getElementById('mic-btn').textContent = '🎤 СЛУШАЮ...';
      logIncident('Активирован голосовой ввод');
    } catch(e){
      notify('⚠ Не удалось запустить микрофон');
    }
  }

  // ===== Реактивное ядро =====
  function setThinking(on){
    coreWrap.classList.toggle('thinking', on);
    loadBar.style.width = on ? (55 + Math.random()*35) + '%' : '6%';
  }
  function flashResponding(){
    coreWrap.classList.add('responding');
    setTimeout(()=> coreWrap.classList.remove('responding'), 900);
  }

  // ===== UI helpers =====
  function addLine(text, who){
    const span = document.createElement('span');
    span.className = who === 'user' ? 'line-user' : 'line-gideon';
    span.style.display = 'block';
    span.textContent = text;
    log.appendChild(span);
    log.scrollTop = log.scrollHeight;
  }

  function addTyping(){
    const div = document.createElement('div');
    div.className = 'typing';
    div.id = 'typing-indicator';
    div.innerHTML = '<span class="dots"><span>.</span><span>.</span><span>.</span></span>';
    log.appendChild(div);
    log.scrollTop = log.scrollHeight;
  }
  function removeTyping(){
    const el = document.getElementById('typing-indicator');
    if(el) el.remove();
  }

  // печать ответа посимвольно — только для коротких реплик,
  // длинные выводятся сразу, иначе чтение/озвучка становятся мучительными
  async function typeAnswer(text){
    if(text.length > 400){
      addLine(text, 'gideon');
      return;
    }
    const span = document.createElement('span');
    span.className = 'line-gideon';
    span.style.display = 'block';
    log.appendChild(span);
    for(let i=0;i<text.length;i++){
      span.textContent += text[i];
      log.scrollTop = log.scrollHeight;
      await new Promise(r=>setTimeout(r, 12));
    }
  }

  // ===== Основной вызов ИИ =====
  async function askGideon(userText){
    setThinking(true);
    addTyping();

    const messages = [...conversation.slice(-40), {role:'user', content:userText}];

    try{
      if(!navigator.onLine) throw new Error('offline: navigator reports no connection');
      const response = await fetch(GIDEON_PROXY_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          max_tokens: 1000,
          system: SYSTEM_PROMPT,
          messages: messages.map(m => ({role: m.role, content: m.content}))
        })
      });
      if(!response.ok){
        const errBody = await response.text().catch(()=> '');
        throw new Error(`HTTP ${response.status}: ${errBody.slice(0,200)}`);
      }
      const data = await response.json();
      const textBlock = (data.content || []).find(b => b.type === 'text');
      const reply = textBlock ? textBlock.text : localFallback(userText);

      removeTyping();
      await typeAnswer(reply);
      flashResponding();
      speak(reply);
      notify('Ответ получен от ИИ-ядра');

      conversation.push({role:'user', content:userText});
      conversation.push({role:'assistant', content:reply});
      await saveMemory();
    } catch(err){
      console.error('Ошибка вызова Гидеон-ядра:', err);
      const reply = localFallback(userText);
      removeTyping();
      await typeAnswer(reply);
      speak(reply);
      triggerAlarm('⚠ Сбой связи с ИИ-ядром — офлайн-ответ');
      conversation.push({role:'user', content:userText});
      conversation.push({role:'assistant', content:reply});
      await saveMemory();
    } finally {
      setThinking(false);
    }
  }

  // ===== История команд (стрелки вверх/вниз) =====
  let cmdHistory = [];
  let historyIndex = -1;

  function sendCmd(){
    const val = cmdInput.value.trim();
    if(!val) return;
    if(isBusy){
      notify('⏳ Гидеон ещё обрабатывает предыдущий запрос, Doctor Wels');
      return;
    }
    addLine(val, 'user');
    cmdInput.value = "";
    coreWrap.style.filter = '';
    cmdHistory.push(val);
    historyIndex = cmdHistory.length;
    logIncident(`Команда от Doctor Wels: "${val.slice(0,60)}"`);

    tryLocalCommand(val).then(handled=>{
      if(handled){
        notify('Локальная команда выполнена');
        return;
      }
      isBusy = true;
      document.querySelector('.send-btn').disabled = true;
      askGideon(val).finally(()=>{
        isBusy = false;
        document.querySelector('.send-btn').disabled = false;
      });
    });
  }

  function quick(text){
    cmdInput.value = text;
    sendCmd();
  }

  function fillTemplate(text){
    cmdInput.value = text;
    cmdInput.focus();
    notify('Впишите имена персонажей вместо "___" и нажмите ВЫПОЛНИТЬ');
  }

  cmdInput.addEventListener('keydown', e=>{
    if(e.key === 'Enter'){ sendCmd(); return; }
    if(e.key === 'ArrowUp'){
      if(cmdHistory.length === 0) return;
      historyIndex = Math.max(0, historyIndex - 1);
      cmdInput.value = cmdHistory[historyIndex] || '';
      e.preventDefault();
    }
    if(e.key === 'ArrowDown'){
      if(cmdHistory.length === 0) return;
      historyIndex = Math.min(cmdHistory.length, historyIndex + 1);
      cmdInput.value = cmdHistory[historyIndex] || '';
      e.preventDefault();
    }
  });

  loadMemory();
  applyVisitVariety();
  updateStreak();
  initArchiveCounter();

  // ===== Модальное окно симулятора =====
  const simModal = document.getElementById('sim-modal');
  const simFrame = document.getElementById('sim-frame');
  const simLiveStat = document.getElementById('sim-live-stat');
