  // приём данных из симулятора (число частиц, взрывы, смена режима)
  let bestRecord = { maxCount: 0, recordMass: 0 };
  const RECORD_KEY = 'gideon-sim-records';
  (async ()=>{
    try{
      const r = await storageGet(RECORD_KEY);
      if(r && r.value) bestRecord = JSON.parse(r.value);
    } catch(e){}
  })();

  let pendingSceneResolve = null;

  window.addEventListener('message', (e)=>{
    if(!e.data || typeof e.data !== 'object') return;
    if(e.data.type === 'sf-stats'){
      simLiveStat.textContent = `активные спидстеры: ${e.data.count} · режим: ${e.data.mode}`;
      const intensity = Math.min(1, e.data.count / 150);
      coreWrap.style.filter = intensity > 0
        ? `drop-shadow(0 0 ${8 + intensity*24}px rgba(79,224,255,${0.5+intensity*0.4}))`
        : '';
      if(e.data.maxCount > bestRecord.maxCount || e.data.recordMass > bestRecord.recordMass){
        const beatCount = e.data.maxCount > bestRecord.maxCount;
        const beatMass = e.data.recordMass > bestRecord.recordMass;
        bestRecord.maxCount = Math.max(bestRecord.maxCount, e.data.maxCount || 0);
        bestRecord.recordMass = Math.max(bestRecord.recordMass, e.data.recordMass || 0);
        storageSet(RECORD_KEY, JSON.stringify(bestRecord));
        if(beatCount || beatMass) notify('🏆 Новый рекорд Спидфорса!');
      }
    }
    if(e.data.type === 'sf-explosion'){
      flashResponding();
      hVibrate(100);
      notify('Всплеск энергии Спидфорса зафиксирован ядром');
    }
    if(e.data.type === 'sf-close'){
      closeSimModal();
    }
    if(e.data.type === 'sf-theme-changed'){
      setTheme(e.data.negative, false);
    }
    if(e.data.type === 'sf-scene' && pendingSceneResolve){
      pendingSceneResolve(e.data.scene);
      pendingSceneResolve = null;
    }
  });

