  const SCENE_KEY = 'gideon-sim-scene';

  async function requestSceneSave(){
    if(!simLoaded || !simModal.classList.contains('open')){
      return "Симулятор не открыт — сохранять нечего. Сначала запустите визуализацию, Doctor Wels.";
    }
    const scene = await new Promise((resolve)=>{
      pendingSceneResolve = resolve;
      simFrame.contentWindow.postMessage({type:'gideon-save-request'}, '*');
      setTimeout(()=>{ if(pendingSceneResolve){ pendingSceneResolve(null); pendingSceneResolve = null; } }, 2000);
    });
    if(!scene) return "Симулятор не ответил вовремя. Попробуйте ещё раз.";
    await storageSet(SCENE_KEY, JSON.stringify(scene));
    return `Сцена сохранена: ${scene.speedsters.length} спидстеров, ${scene.portals.length} порталов.`;
  }

  async function requestSceneLoad(){
    if(!simLoaded || !simModal.classList.contains('open')) openSimModal();
    let scene = null;
    try{
      const r = await storageGet(SCENE_KEY);
      if(r && r.value) scene = JSON.parse(r.value);
    } catch(e){}
    if(!scene) return "Сохранённых сцен не найдено, Doctor Wels.";
    setTimeout(()=>{
      try{ simFrame.contentWindow.postMessage({type:'gideon-load-scene', scene}, '*'); }catch(e){}
    }, simLoaded ? 50 : 500);
    return "Загружаю сохранённую сцену в симулятор.";
  }

