  // ===== Пять скрытых триггеров архивных файлов — каждый в своём месте =====
  function makeArchiveTrigger(elId, clicksNeeded, archiveIdx, windowMs){
    let stamps = [];
    const el = document.getElementById(elId);
    if(!el) return;
    el.addEventListener('click', ()=>{
      const now = Date.now();
      stamps.push(now);
      stamps = stamps.filter(t => now - t < windowMs);
      if(stamps.length >= clicksNeeded){
        stamps = [];
        showArchive(archiveIdx);
      }
    });
  }
