// ===== combined from index.html script blocks =====


  // Регистрация офлайн-кэша + индикатор обновления.
  // Сработает только на реальном https-хостинге — внутри превью Claude
  // или при открытии как локальный файл просто тихо пропустится.
  if('serviceWorker' in navigator && window.isSecureContext){
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('./sw.js').then((reg) => {
        reg.addEventListener('updatefound', () => {
          const newWorker = reg.installing;
          if(!newWorker) return;
          newWorker.addEventListener('statechange', () => {
            if(newWorker.state === 'installed' && navigator.serviceWorker.controller){
              showUpdateBanner(newWorker);
            }
          });
        });
      }).catch(()=>{});

      let refreshing = false;
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        if(refreshing) return;
        refreshing = true;
        window.location.reload();
      });
    });
  }

  function showUpdateBanner(newWorker){
    if(document.getElementById('sw-update-banner')) return;
    const banner = document.createElement('div');
    banner.id = 'sw-update-banner';
    banner.textContent = '⟳ Доступно обновление — нажмите, чтобы применить';
    banner.style.cssText = 'position:fixed;bottom:0;left:0;right:0;z-index:600;'
      + 'background:#0a0e14;border-top:1px solid #4fe0ff;color:#4fe0ff;'
      + 'font-family:"JetBrains Mono",monospace;font-size:12px;letter-spacing:0.05em;'
      + 'padding:12px 16px;text-align:center;cursor:pointer;'
      + 'box-shadow:0 -4px 20px rgba(79,224,255,0.2);';
    banner.onclick = () => {
      newWorker.postMessage({ type: 'SKIP_WAITING' });
      banner.textContent = '⟳ Обновляю...';
    };
    document.body.appendChild(banner);
  }
